import { readFileSync, existsSync } from 'node:fs';
const read = file => readFileSync(file, 'utf8');
const tests = [];
function check(name, passed) { tests.push({ name, passed: Boolean(passed) }); console.log(`${passed ? 'PASS' : 'FAIL'}: ${name}`); }
const scope = read('server/_crm-utils.ts');
const report = read('server/crm/reports.ts');
const crmUi = read('src/crm/pages/CrmDashboardPage.tsx');
const crmApi = read('server/crm/dashboard.ts');
const dashboard = read('server/_dashboard-data.ts');
const rootUi = read('src/pages/DashboardPage.tsx');
const attendance = read('src/attendance/AttendancePage.tsx');
const attendanceApi = read('server/attendance.ts');
const marketing = read('src/marketing/workflow/CreatePage.tsx');
const importApi = read('server/_crm-sheet-import.ts');
const inbox = read('server/crm/inbox.ts');
check('CRM transferred managers see only the CURRENT primary CRM branch', scope.includes('access.branchCodes.slice(0, 1)') && scope.includes('core.user_system_branches') && scope.includes('not ${scope.branchRestricted}::boolean'));
check('CRM leads, conversations, history, media, data review and unread are scoped by current branch', ['server/crm/leads.ts','server/crm/conversations.ts','server/crm/history.ts','server/crm/data-review.ts','server/crm/unread.ts','server/crm/media.ts'].every(f=>read(f).includes('crmLeadScopeSql') || read(f).includes('currentCrmLeadBranchSql')));
check('CRM inbox cannot bypass current branch by using management privileges', inbox.includes('l.id is not null and ${leadScope}') && inbox.includes('المحادثة ليست ضمن فرعك الحالي'));
check('CRM sale facts preserve historical branch and restrict visibility to current branch', report.includes('const transactionCurrentBranchCodeSql = assignedRepBranch("base")') && report.includes('(${transactionBranchCodeSql}) as branch_code') && report.includes('(${transactionCurrentBranchCodeSql})=any(${scope.branchCodes}::text[])'));
check('CRM dashboard has month default, range control and both API requests filtered by dates', crmUi.includes('useState<"month" | "range">("month")') && crmUi.includes('type="month"') && crmUi.includes('from: activeDates.from') && crmUi.includes('dashboardPeriod: 1'));
check('CRM only non-qualified uses status-change dates while older customers in all other statuses stay visible', crmApi.includes('crmVisibleCustomerCohortSql') && report.includes('crmVisibleCustomerCohortSql') && read('server/_crm-customer-cohort.ts').includes("e.new_status='غير مؤهل'"));
check('Removed online branch from finance CRM selector', !crmUi.includes('item.code === "online"') && read('src/crm/components/LeadDrawer.tsx').includes('branch.code !== "online"'));
check('CRM lead-sheet routing is short-locked and deduplicates by normalized phone', importApi.includes('tryWithDatabaseAdvisoryLock') && importApi.includes('await findExistingPhone(check.phoneNormalized, legacyCache)') && importApi.includes('const definitions = await getCustomerFieldDefinitions()'));
check('Attendance Friday is one evening period using configured Friday hours', attendanceApi.includes('isFriday && fridayScheduleEnabled') && attendanceApi.includes('"الفترة المسائية"') && attendanceApi.includes('fridayStartTime') && attendanceApi.includes('fridayEndTime'));
check('Attendance leave status is displayed as vacation and preserves permission times', attendance.includes('return row.earlyDeparturePermission') && attendance.includes('"إجازة"') && attendanceApi.includes('earlyDeparturePermission'));
check('Attendance expected actual and difference hours are in daily table and PDF Excel rather than detached summary', ['ساعات الدوام المفترضة','ساعات العمل الفعلية','الفرق (مفترض − فعلي)'].every(x => attendance.includes(x)) && !attendance.includes('attendance-hours-summary panel') && !attendance.includes('worksheet("ملخص الساعات", hourHeaders, hourRows)'));
check('Campaign/agenda tasks list every requirement with idea and no separate search field', marketing.includes('<optgroup') && marketing.includes('product.idea') && !marketing.includes('productSearch'));
check('Campaign/agenda preview includes date, product, idea, platform, publication type and optional budget', marketing.includes('setPreviewOpen(current => !current)') && marketing.includes('dateLabel') && marketing.includes('productId') && marketing.includes('postTypeId') && marketing.includes('budget: platform?.budget') && marketing.includes('planEntriesPayload(entries, kind)'));
check('Main dashboard customer total, departments, reps, and growth all share a single deduplicated SQL cohort', dashboard.includes('scoped_leads as (') && dashboard.includes('distinct on (coalesce') && dashboard.includes('from scoped_leads') && dashboard.includes('from reps r') && dashboard.includes('from daily d'));
check('Main dashboard replaces conversations with reps and preserves non-assigned customers', rootUi.includes('analytics:representatives') && rootUi.includes('المناديب') && dashboard.includes('غير موزع') && dashboard.includes('other_customers'));
check('All source files remain in full tree', ['package.json','server/attendance.ts','server/crm/dashboard.ts','server/crm/leads.ts','src/pages/DashboardPage.tsx','src/marketing/workflow/CreatePage.tsx'].every(existsSync));
console.log(`Integrated MZJ checks: ${tests.filter(t=>t.passed).length}/${tests.length}`);
if(tests.some(t=>!t.passed)) process.exit(1);
